def next_smallest_palindrome(num):
    numstr = str(num)
    length = len(numstr)
    # Generate the next palindrome based on the length
    if all(c == '9' for c in numstr):
        return 10 ** length + 1
    # Create the palindrome by mirroring the left half
    left = int(numstr[: (length + 1) // 2])
    while True:
        left += 1
        pal = str(left) + str(left)[:- (length % 2)]
        if int(pal) > num:
            return int(pal)
```

