def next_smallest_palindrome(num):
    numstr = str(num)
    length = len(numstr)

    # Helper function to create the next palindrome
    def create_palindrome(s, is_odd):
        if is_odd:
            return s + s[:-1][::-1]
        else:
            return s + s[::-1]

    # Start with the smallest possible palindrome greater than num
    if num == 99:
        return 101

    # Increment the middle part and generate palindrome
    mid = (length + 1) // 2
    prefix = numstr[:mid]
    prefix = str(int(prefix) + 1)

    if len(prefix) > mid:
        return 10**length + 1

    if length % 2 == 0:
        candidate = create_palindrome(prefix, False)
    else:
        candidate = create_palindrome(prefix, True)

    return int(candidate)
```

