def next_smallest_palindrome(num):
    numstr = str(num)
    length = len(numstr)

    # Handle the case where the number is all 9s
    if all(c == '9' for c in numstr):
        return 10**length - 1

    # Create the next palindrome by mirroring the left half
    left = numstr[: (length + 1) // 2]
    next_left = str(int(left) + 1)

    if len(next_left) > len(left):
        return 10**length - 1

    if length % 2 == 0:
        next_pal = next_left + next_left[::-1]
    else:
        next_pal = next_left + next_left[-2::-1]

    return int(next_pal)
