def next_smallest_palindrome(num):
    numstr = str(num)
    length = len(numstr)

    # Helper function to create the next palindrome
    def create_palindrome(s, is_odd):
        if is_odd:
            return s + s[-2::-1]
        else:
            return s + s[-1::-1]

    # Check if the number is already a palindrome
    if numstr == numstr[::-1]:
        return int(create_palindrome(numstr, True)) if length == 1 else int(create_palindrome(numstr, False))

    # Generate the next palindrome
    half = numstr[:(length + 1) // 2]
    next_half = str(int(half) + 1)

    if len(next_half) > len(half):
        return int('1' + '0' * (length - 1) + '1')

    if length % 2 == 0:
        candidate = create_palindrome(next_half, False)
    else:
        candidate = create_palindrome(next_half, True)

    return int(candidate)
```

