def get_total_number_of_sequences(m, n):
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        dp[i][1] = 1  # Only one sequence of length 1 for each number

    for length in range(2, n + 1):
        for current in range(1, m + 1):
            # Sum all sequences of length `length-1` that can be extended by `current`
            # The previous number must be <= current // 2
            dp[current][length] = sum(dp[prev][length - 1] for prev in range(1, current // 2 + 1))

    return dp[m][n]
