def get_total_number_of_sequences(m, n):
    # T[i][j] represents the number of sequences of length j with maximum element <= i
    T = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        T[i][1] = 1  # A sequence of length 1 can be any number from 1 to i

    for j in range(2, n + 1):
        for i in range(1, m + 1):
            # Count sequences where the last element is i
            # The previous element must be <= i // 2
            T[i][j] = T[i // 2][j - 1]

    return T[m][n]
