def max_product(arr):
    n = len(arr)
    max_product = [0] * n
    for i in range(n):
        max_product[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] >= arr[j - 1]:
                max_product[j] = max(max_product[j], max_product[j - 1] * arr[j])
            else:
                break
    return max(max_product)
