def max_product(arr):
    n = len(arr)
    # dp[i] will store the maximum product of an increasing subsequence ending at index i
    dp = [arr[i] for i in range(n)]

    for i in range(n):
        for j in range(i + 1, n):
            if arr[j] > arr[i]:
                # Update dp[j] if multiplying with dp[i] gives a larger product
                dp[j] = max(dp[j], dp[i] * arr[j])

